import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.Bqa2y7hU.js";const r=JSON.parse('{"title":"安装","description":"在 Ubuntu 24.04 服务器上安装 Xiaoyi_QQ_V4：.deb 包、tar.gz 便携包与直接运行二进制三种方式。","frontmatter":{"title":"安装","description":"在 Ubuntu 24.04 服务器上安装 Xiaoyi_QQ_V4：.deb 包、tar.gz 便携包与直接运行二进制三种方式。"},"headers":[],"relativePath":"deploy/install.md","filePath":"deploy/install.md","lastUpdated":1790419519000}'),e={name:"deploy/install.md"};function l(p,s,h,d,o,c){return i(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="安装-🌱" tabindex="-1">安装 🌱 <a class="header-anchor" href="#安装-🌱" aria-label="Permalink to &quot;安装 🌱&quot;">​</a></h1><p>这页讲怎么把 Xiaoyi_QQ_V4 装到服务器上并让它跑起来。读完你能完成：选择安装方式、确认前置依赖、启动并确认服务状态，然后进入首次配置。</p><p>Xiaoyi_QQ_V4 是<strong>单二进制</strong>程序，前端资源已经内嵌进可执行文件，不需要额外部署 Web 服务。</p><h2 id="_1-确认前置依赖" tabindex="-1">1. 确认前置依赖 <a class="header-anchor" href="#_1-确认前置依赖" aria-label="Permalink to &quot;1. 确认前置依赖&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>系统</td><td>Ubuntu 24.04 x86_64（推荐），Debian 系同版本亦可</td></tr><tr><td>运行库（动态链接版）</td><td><code>libpq5</code>、<code>libssl3t64</code></td></tr><tr><td>数据库</td><td>一个可用的 PostgreSQL 实例（本地或远程都行）</td></tr><tr><td>消息队列</td><td><strong>不需要</strong>。本产品不使用 Redis 或任何消息队列</td></tr></tbody></table><p>Xiaoyi_QQ_V4 <strong>不依赖</strong> Redis、RabbitMQ、Nginx 之类的中间件；除了 PostgreSQL，没有别的外部服务。</p><p>安装 .deb 前如果不确定运行库是否齐全，先补上：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 补装动态链接所需的两个运行库（Ubuntu 24.04 包名）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libpq5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libssl3t64</span></span></code></pre></div><h2 id="_2-方式一-安装-deb-包-推荐" tabindex="-1">2. 方式一：安装 <code>.deb</code> 包（推荐） <a class="header-anchor" href="#_2-方式一-安装-deb-包-推荐" aria-label="Permalink to &quot;2. 方式一：安装 \`.deb\` 包（推荐）&quot;">​</a></h2><p>Ubuntu 原生安装包，一条命令装完并自动接好 systemd 服务。安装包文件名形如 <code>xiaoyi-qq-c_0.1.0_amd64.deb</code>。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 安装包本体；会自动装到 /opt/xiaoyi_qq_c/ 并注册 systemd 服务</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dpkg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xiaoyi-qq-c_0.1.0_amd64.deb</span></span></code></pre></div><p>装完后会发生三件事：</p><ol><li>程序文件落到 <code>/opt/xiaoyi_qq_c/</code>；</li><li>systemd 服务 <code>xiaoyi-qq-c</code> 被 <code>enable</code> 并启动；</li><li>因为还没有安装标记，服务进入 <strong>Web 安装向导</strong>模式，监听 <code>8080</code>。</li></ol><p>接着浏览器打开 <code>http://&lt;你的服务器IP&gt;:8080/install</code> 完成首次配置，详见 <a href="/RuaBot.Doc/deploy/config">首次配置</a>。</p><div class="tip custom-block"><p class="custom-block-title">安装后的目录布局</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/opt/xiaoyi_qq_c/</span></span>
<span class="line"><span>  xbot                    # 主程序（前端已内嵌）</span></span>
<span class="line"><span>  config/bot.toml         # 配置文件</span></span>
<span class="line"><span>  migrations/*.sql        # 数据库迁移脚本（启动时自动应用）</span></span>
<span class="line"><span>  plugins/*.so            # 内置插件</span></span>
<span class="line"><span>  .installed              # 安装完成标记（向导跑完才生成）</span></span></code></pre></div></div><h2 id="_3-方式二-tar-gz-便携包-install-sh" tabindex="-1">3. 方式二：<code>tar.gz</code> 便携包 + <code>install.sh</code> <a class="header-anchor" href="#_3-方式二-tar-gz-便携包-install-sh" aria-label="Permalink to &quot;3. 方式二：\`tar.gz\` 便携包 + \`install.sh\`&quot;">​</a></h2><p>便携包和 <code>.deb</code> 目录结构一致，附带一个安装脚本，会帮你装依赖并注册 systemd 服务。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 解压便携包</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xiaoyi-qq-c_0.1.0_amd64.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xiaoyi-qq-c</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 安装脚本：装依赖 + 注册 systemd 服务（需要 root）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./install.sh</span></span></code></pre></div><p>装完后同样访问 <code>http://&lt;你的服务器IP&gt;:8080/install</code> 走安装向导。</p><h2 id="_4-方式三-直接运行二进制-开发-测试" tabindex="-1">4. 方式三：直接运行二进制（开发 / 测试） <a class="header-anchor" href="#_4-方式三-直接运行二进制-开发-测试" aria-label="Permalink to &quot;4. 方式三：直接运行二进制（开发 / 测试）&quot;">​</a></h2><p>不想用 systemd 时，可以直接把程序跑起来，适合本机调试。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 必须先进到程序所在目录（项目根目录），再启动</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/xiaoyi_qq_c</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./xbot</span></span></code></pre></div><p>Windows 上开发测试同理，在项目根目录执行 <code>build\\src\\xbot.exe</code>，依赖的 DLL 已经放在可执行文件旁边。</p><div class="danger custom-block"><p class="custom-block-title">必须在项目根目录启动</p><p><code>config/</code>、<code>plugins/</code>、<code>migrations/</code> 以及安装标记 <code>.installed</code> 都是<strong>相对当前工作目录</strong>解析的。</p><p>如果你在其他目录用绝对路径启动（例如 <code>/opt/xiaoyi_qq_c/xbot</code>），程序会找不到 <code>config/bot.toml</code>，也不会认出 <code>.installed</code>。systemd 服务里已经通过 <code>WorkingDirectory</code> 固定了目录，手动运行时请自己 <code>cd</code> 进去。</p></div><h2 id="_5-密钥文件-请务必备份" tabindex="-1">5. 密钥文件：请务必备份 <a class="header-anchor" href="#_5-密钥文件-请务必备份" aria-label="Permalink to &quot;5. 密钥文件：请务必备份&quot;">​</a></h2><p>首次启动时程序会在 <code>config/secrets.env</code> 里生成两个随机密钥（权限 600），用于加密数据库中的敏感字段与签发登录态。</p><div class="danger custom-block"><p class="custom-block-title">这个文件丢了，数据就再也解不开</p><ul><li><strong>请把 <code>config/secrets.env</code> 复制一份到别的地方保存</strong>（离线介质、密码管理器都行）。 它不在任何版本库里，丢了<strong>没有任何办法恢复</strong>，联系授权方也恢复不了。</li><li><strong>迁移服务器、重装、换机器时，它必须和数据库一起搬</strong>。只搬数据库不搬它，等于数据全废。</li><li>不要把它发给任何人，也不要提交进任何代码仓库。</li></ul><p><code>./xbot --help</code> 可以查看全部命令；<code>./xbot --verify</code> 可以校验程序文件自身的完整性。</p></div><h2 id="_6-启动、停止与查看状态" tabindex="-1">6. 启动、停止与查看状态 <a class="header-anchor" href="#_6-启动、停止与查看状态" aria-label="Permalink to &quot;6. 启动、停止与查看状态&quot;">​</a></h2><p><code>.deb</code> 与 <code>install.sh</code> 两种方式都用 systemd 托管服务，服务名统一是 <code>xiaoyi-qq-c</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看运行状态（是否 active、最近日志）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xiaoyi-qq-c</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 启动 / 停止 / 重启</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xiaoyi-qq-c</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xiaoyi-qq-c</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xiaoyi-qq-c</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 设为开机自启 / 取消</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xiaoyi-qq-c</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xiaoyi-qq-c</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 实时跟踪日志（按 Ctrl+C 退出）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xiaoyi-qq-c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre></div><p>直接跑二进制时，用 <code>Ctrl+C</code> 停止即可。</p><h2 id="_7-确认服务已经起来" tabindex="-1">7. 确认服务已经起来 <a class="header-anchor" href="#_7-确认服务已经起来" aria-label="Permalink to &quot;7. 确认服务已经起来&quot;">​</a></h2><p>两个端口分别承担不同职责：</p><table tabindex="0"><thead><tr><th>端口</th><th>用途</th></tr></thead><tbody><tr><td><code>8080</code></td><td>控制台 / Web 安装向导（人访问的界面）</td></tr><tr><td><code>8081</code></td><td>适配器数据面（QQ 平台连接走这里，例如 OneBot 反向 WS）</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 看端口有没有在监听</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lntp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;8080|8081&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 健康检查应该返回 {&quot;status&quot;:&quot;ok&quot;}</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/healthz</span></span></code></pre></div><details class="details custom-block"><summary>截图占位</summary><p>截一张浏览器打开 <code>http://&lt;你的服务器IP&gt;:8080/install</code> 时的安装向导首页，用来展示向导长什么样（本次文档不放图）。</p></details><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/deploy/config">首次配置</a></li><li><a href="/RuaBot.Doc/deploy/reverse-proxy">反向代理与 HTTPS</a></li><li><a href="/RuaBot.Doc/deploy/ops">备份与运维</a></li></ul>`,38)])])}const g=a(e,[["render",l]]);export{r as __pageData,g as default};
